# owner: platform
"""Plain-text absence notices for parents."""

from rosterkit.attendance import days_missed

def _check_owner(student, marks):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for student {mark.student_id} does "
                f"not belong to {student.student_id}"
            )

def _bullet(when):
    return f"- {when:%B} {when.day}, {when.year}"

def _compose(student, missed):
    name = f"{student.first_name} {student.last_name}"
    total = len(missed)
    noun = "day" if total == 1 else "days"
    intro = f"{name} was absent for {total} {noun}:"
    items = "\n".join(_bullet(when) for when in missed)
    return f"Dear parent or guardian,\n\n{intro}\n{items}\n"

# ---
def build_notice(student, marks):
    """Notice of absences; ValueError if none or foreign."""
    marks = list(marks)
    _check_owner(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to report")
    return _compose(student, missed)
